  let activeProfile=null,chartList=[],attendanceClassId='',attendanceDate=Store?.isoDate?.(new Date())||'',historyFilters={from:'',to:'',classId:'all',q:'',teacherId:'all',status:'all'},feeFilters={month:String(new Date().getMonth()+1),year:String(new Date().getFullYear()),classId:'all',shift:'all',enrollment:'all',status:'all',q:''},dashMonth=`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`;
  const root=()=>$('#view-root'),modal=()=>$('#modal-root'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cash=n=>`$${Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`,today=()=>Store.isoDate(new Date()),pretty=d=>d?new Date(`${String(d).slice(0,10)}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—',initals=n=>String(n||'?').trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase(),activeYear=()=>Store.getAcademicYears().find(y=>y.isActive)?.name||'—';
