  function dashboard(){const students=Store.getStudents(),active=students.filter(s=>s.enrollmentStatus==='Active'),fees=Store.getFees(),[year,month]=dashMonth.split('-'),monthly=fees.filter(f=>f.billingYear==year&&f.billingMonth==Number(month)),paid=monthly.filter(f=>f.status==='Paid'),unpaid=monthly.filter(f=>f.balance>0),collected=monthly.reduce((s,f)=>s+f.amountPaid,0),outstanding=monthly.reduce((s,f)=>s+f.balance,0),paidStudents=new Set(paid.map(f=>f.studentId)).size,unpaidStudents=new Set(unpaid.map(f=>f.studentId)).size,classes=Store.getClasses().filter(c=>c.isActive),teachers=Store.getTeachers().filter(t=>t.isActive),attendance=Store.getAttendance().filter(a=>a.date===today()),eligible=active.filter(s=>String(s.registrationDate)<=today()),present=attendance.filter(a=>a.status==='Present').length,rate=eligible.length?Math.round(present/eligible.length*100):0,history=Store.getAcademicHistory,primary=active.filter(s=>s.educationLevel==='primary').length,secondary=active.filter(s=>s.educationLevel==='secondary').length,promos=Store.getPromotions(),years=Store.getAcademicYears(),monthOptions=Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${Number(month)===i+1?'selected':''}>${new Date(2026,i,1).toLocaleString('en-US',{month:'long'})}</option>`).join(''),yearOptions=[...new Set(fees.map(f=>String(f.billingYear)))].sort().reverse().map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('');
    root().innerHTML=`<div class="page-enter">${head('Good morning, Admin 👋',`Al-Hikma Academy · ${pretty(today())}`,`<button class="btn btn-primary" data-adv-action="open-student"><i data-feather="user-plus"></i> Register student</button>`)}<div class="dash-filter card"><span><i data-feather="filter"></i> Fee overview</span><select class="filter-select" id="dash-month">${monthOptions}</select><select class="filter-select" id="dash-year">${yearOptions}</select><span class="dash-filter-label">${pretty(`${year}-${month}-01`)}</span></div><div class="metric-grid advanced-metrics">${metric('users','ic-blue','Active students',active.length,'Currently enrolled')}${metric('dollar-sign','ic-green','Fees collected',cash(collected),`For ${new Date(Number(year),Number(month)-1,1).toLocaleString('en-US',{month:'long'})} ${year}`)}${metric('alert-circle','ic-amber','Outstanding balance',cash(outstanding),`${unpaid.length} fee records with balance`)}${metric('user-check','ic-purple','Paid students',paidStudents,`${unpaidStudents} students have unpaid balances`)}${metric('users','ic-blue','Teachers',teachers.length,'Active teacher accounts')}${metric('book-open','ic-green','Active classes',classes.length,'Across primary and secondary')}${metric('check-circle','ic-amber','Attendance today',`${rate}%`,`${attendance.length} recorded · Present / eligible`)}${metric('trending-up','ic-purple','Students promoted',promos.filter(p=>p.status==='Promoted').length,'All academic years')}</div><section class="academic-overview card"><div class="card-heading"><div><h3>Academic overview</h3><p>School-wide enrollment and year status</p></div><button class="text-link" data-adv-view="academic-years">Manage academic years →</button></div><div class="academic-overview-grid"><div><small>Primary students</small><strong>${primary}</strong></div><div><small>Secondary students</small><strong>${secondary}</strong></div><div><small>Graduated</small><strong>${students.filter(s=>s.graduationStatus).length}</strong></div><div><small>Current academic year</small><strong class="year-overview">${esc(activeYear())}</strong></div><div><small>Repeating</small><strong>${promos.filter(p=>p.status==='Repeating').length}</strong></div><div><small>Active classes</small><strong>${classes.length}</strong></div></div></section><div class="dashboard-grid advanced-charts"><article class="card chart-card"><div class="card-heading"><div><h3>Fee collection</h3><p>Collected and outstanding by billing month</p></div></div><div class="chart-wrap"><canvas id="adv-fee-chart"></canvas></div></article><article class="card chart-card"><div class="card-heading"><div><h3>Today's attendance</h3><p>Present, absent, late, and excused</p></div></div><div class="attendance-chart-wrap"><canvas id="adv-att-chart"></canvas></div><div class="chart-legend"><span>Present ${attendance.filter(a=>a.status==='Present').length}</span><span>Absent ${attendance.filter(a=>a.status==='Absent').length}</span><span>Late ${attendance.filter(a=>a.status==='Late').length}</span><span>Excused ${attendance.filter(a=>a.status==='Excused').length}</span></div></article></div><div class="bottom-grid"><article class="card table-card"><div class="card-heading"><div><h3>Recent activity</h3><p>Latest student, payment, attendance, and class updates</p></div></div><div class="activity-list">${recentActivities()}</div></article><article class="card"><div class="card-heading"><div><h3>Quick actions</h3><p>Common school administration tasks</p></div></div><div class="quick-links"><button class="quick-link" data-adv-action="open-student"><span><i data-feather="user-plus"></i></span><strong>Register student</strong><small>Enroll a student</small></button><button class="quick-link" data-adv-view="fees"><span><i data-feather="credit-card"></i></span><strong>Record fee payment</strong><small>View monthly fees</small></button><button class="quick-link" data-adv-action="open-class"><span><i data-feather="book-open"></i></span><strong>Create class</strong><small>Set up a class</small></button><button class="quick-link" data-adv-action="open-teacher"><span><i data-feather="user-check"></i></span><strong>Add teacher</strong><small>Create teacher access</small></button><button class="quick-link" data-adv-view="attendance"><span><i data-feather="check-square"></i></span><strong>Mark attendance</strong><small>Record today's register</small></button><button class="quick-link" data-adv-view="reports"><span><i data-feather="bar-chart-2"></i></span><strong>Generate report</strong><small>See school insights</small></button></div></article></div></div>`;
    $('#dash-month').addEventListener('change',()=>{dashMonth=`${$('#dash-year').value}-${$('#dash-month').value}`;render('dashboard');});$('#dash-year').addEventListener('change',()=>{dashMonth=`${$('#dash-year').value}-${$('#dash-month').value}`;render('dashboard');});
    const labels=Array.from({length:6},(_,i)=>{const d=new Date(Number(year),Number(month)-1-i,1);return {label:d.toLocaleString('en-US',{month:'short'}),key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};}).reverse(),data=Store.getFees();chartList.push(new Chart($('#adv-fee-chart'),{type:'bar',data:{labels:labels.map(x=>x.label),datasets:[{label:'Collected',data:labels.map(x=>data.filter(f=>f.billingKey===x.key).reduce((s,f)=>s+f.amountPaid,0)),backgroundColor:'#C2410C',borderRadius:5},{label:'Outstanding',data:labels.map(x=>data.filter(f=>f.billingKey===x.key).reduce((s,f)=>s+f.balance,0)),backgroundColor:'#f5c8b8',borderRadius:5}]},options:chartOptions()}));chartList.push(new Chart($('#adv-att-chart'),{type:'doughnut',data:{labels:['Present','Absent','Late','Excused'],datasets:[{data:['Present','Absent','Late','Excused'].map(s=>attendance.filter(a=>a.status===s).length),backgroundColor:['#10b981','#ef4444','#f59e0b','#94a3b8'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'70%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,font:{size:9}}}}}}));}
