  function recentActivities(){const events=[];Store.getStudents().slice(0,4).forEach(s=>events.push({time:s.registrationDate,title:'Student registered',detail:s.fullName,icon:'user-plus'}));Store.getPayments().slice(0,4).forEach(p=>{const s=Store.getStudents().find(x=>x.id===p.studentId);events.push({time:p.paymentDate,title:`Fee payment · ${cash(p.amountPaid)}`,detail:`${s?.fullName||p.studentId} · ${p.paymentMethod}`,icon:'dollar-sign'});});Store.getAttendance().slice(-3).forEach(a=>{const s=Store.getStudents().find(x=>x.id===a.studentId);events.push({time:a.createdAt||a.date,title:`Attendance · ${a.status}`,detail:s?.fullName||a.studentId,icon:'check-square'});});Store.getTeachers().slice(0,2).forEach(t=>events.push({time:t.createdAt||today(),title:'Teacher account',detail:t.fullName,icon:'user-check'}));Store.getPromotions().slice(-2).forEach(p=>events.push({time:p.date,title:`Student ${p.status.toLowerCase()}`,detail:Store.getStudents().find(s=>s.id===p.studentId)?.fullName||p.studentId,icon:'trending-up'}));return events.sort((a,b)=>String(b.time).localeCompare(String(a.time))).slice(0,7).map(e=>`<div class="activity-item"><span class="activity-item-icon"><i data-feather="${e.icon}"></i></span><span><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></span><time>${pretty(String(e.time).slice(0,10))}</time></div>`).join('')||'<div class="empty-state">No activity yet.</div>';}
  function attendanceView(){const classes=Store.getClasses().filter(c=>c.isActive),current=classes.find(c=>c.id===attendanceClassId)||classes[0];if(current)attendanceClassId=current.id;attendanceDate||=today();const roster=current?Store.getEligibleClassStudents(current.id,attendanceDate):[],records=current?Store.getClassAttendance(current.id,attendanceDate):[];root().innerHTML=`<div class="page-enter">${head('Xaadirinta · Attendance','Select a class and date. Students are eligible only from their registration date.',`<button class="btn btn-secondary" data-attendance-report><i data-feather="download"></i> Export register</button>`)}<article class="card advanced-table-card attendance-admin-card"><div class="advanced-toolbar attendance-toolbar"><div><strong class="toolbar-title">Class attendance register</strong><small class="table-subline">No earlier attendance is generated for newly enrolled students.</small></div><div class="attendance-toolbar-controls"><select id="admin-attendance-class" class="filter-select"><option value="">Select class</option>${classes.map(c=>`<option value="${esc(c.id)}" ${c.id===current?.id?'selected':''}>${esc(c.name)} · ${esc(c.shift)}</option>`).join('')}</select><input type="date" id="admin-attendance-date" class="date-input" value="${esc(attendanceDate)}" max="${today()}"><button class="btn btn-secondary btn-sm" data-attendance-today>Today</button></div></div>${!current?'<div class="empty-state">Create an active class to take attendance.</div>':`<div class="table-responsive"><table class="attendance-admin-table"><thead><tr><th>Present / Jooga</th><th>STUDENT</th><th>STATUS</th><th>PREVIOUSLY SAVED</th></tr></thead><tbody>${roster.map(s=>{const saved=records.find(a=>a.studentId===s.id),checked=saved?.status!=='Absent',status=saved?.status||'Present';return `<tr><td><input class="attendance-presence-checkbox" type="checkbox" data-presence-id="${esc(s.id)}" aria-label="Mark ${esc(s.fullName)} present" ${checked?'checked':''}></td><td><div class="student-name"><span class="student-initials student-avatar-large">${initals(s.fullName)}</span><span><strong>${esc(s.fullName)}</strong><small>${esc(s.id)} · Registered ${pretty(s.registrationDate)}</small></span></div></td><td><select class="attendance-secondary-status" data-attendance-status="${esc(s.id)}" aria-label="Attendance status for ${esc(s.fullName)}" ${checked?'':'disabled'}><option value="Present" ${status==='Present'?'selected':''}>Present</option><option value="Late" ${status==='Late'?'selected':''}>Late</option><option value="Excused" ${status==='Excused'?'selected':''}>Excused</option></select></td><td>${saved?`<span class="badge ${statusBadge(saved.status)}">${esc(saved.status)}</span>`:'<span class="muted">Not recorded</span>'}</td></tr>`;}).join('')||'<tr><td colspan="4"><div class="empty-state"><i data-feather="users"></i><strong>No students eligible on this date</strong><p>Students registered after this date are excluded.</p></div></td></tr>'}</tbody></table></div><div class="teacher-register-save"><span>${roster.length} eligible students · ${pretty(attendanceDate)}</span><div class="teacher-save-actions"><button class="btn btn-secondary btn-sm" data-attendance-mark-all>Mark all present</button><button class="btn btn-secondary btn-sm" data-attendance-mark-absent>Mark all absent</button><button class="btn btn-primary btn-sm" data-attendance-save ${roster.length?'':'disabled'}><i data-feather="save"></i> Save attendance</button></div></div>`}</article><div class="teacher-access-notice"><i data-feather="info"></i> Attendance is tied to the class and date, and duplicate student/class/day records are updated rather than duplicated.</div></div>`;}
  function filteredAttendanceHistory(scope='admin'){const teacher=scope==='teacher'?window.TeacherPortal?.currentTeacher?.():null,assigned=teacher?new Set(Store.getTeacherClasses(teacher.id).map(c=>c.id)):null,classes=Store.getClasses(),students=Store.getStudents(),teachers=Store.getTeachers();return Store.getAttendance().filter(a=>!assigned||assigned.has(a.classId)&&(a.recordedBy===teacher.id||a.teacherId===teacher.id)).map(a=>({...a,student:students.find(s=>s.id===a.studentId),cls:classes.find(c=>c.id===a.classId),teacher:teachers.find(t=>t.id===(a.teacherId||a.recordedBy))})).filter(a=>a.student).filter(a=>(!historyFilters.from||a.date>=historyFilters.from)&&(!historyFilters.to||a.date<=historyFilters.to)&&(historyFilters.classId==='all'||a.classId===historyFilters.classId)&&(!historyFilters.q||[a.student.fullName,a.student.id].some(v=>String(v||'').toLowerCase().includes(historyFilters.q.toLowerCase())))&&(scope==='teacher'||historyFilters.teacherId==='all'||a.recordedBy===historyFilters.teacherId||a.teacher?.id===historyFilters.teacherId)&&(historyFilters.status==='all'||a.status===historyFilters.status)).sort((a,b)=>b.date.localeCompare(a.date)||a.student.fullName.localeCompare(b.student.fullName));}
  function attendanceHistoryView(){const records=filteredAttendanceHistory(),counts=Object.fromEntries(['Present','Absent','Late','Excused'].map(s=>[s,records.filter(a=>a.status===s).length])),denom=counts.Present+counts.Absent+counts.Late,rate=denom?Math.round((counts.Present+counts.Late)/denom*100):0,classes=Store.getClasses(),teachers=Store.getTeachers();root().innerHTML=`<div class="page-enter">${head('Attendance History · Taariikhda Xaadirinta','Review, filter, export, and correct the school attendance register.',`<button class="btn btn-secondary" data-history-export><i data-feather="download"></i> Export CSV</button><button class="btn btn-primary" data-history-print><i data-feather="printer"></i> Print</button>`)}<div class="history-metrics"><article class="card"><small>Total records</small><strong>${records.length}</strong></article>${['Present','Absent','Late','Excused'].map(s=>`<article class="card"><small>${s}</small><strong>${counts[s]}</strong></article>`).join('')}<article class="card"><small>Attendance %</small><strong>${rate}%</strong></article></div><article class="card history-filter-card"><div class="history-filter-grid"><label>From<input type="date" data-history-filter="from" value="${esc(historyFilters.from)}"></label><label>To<input type="date" data-history-filter="to" value="${esc(historyFilters.to)}"></label><label>Class<select data-history-filter="classId"><option value="all">All classes</option>${classes.map(c=>`<option value="${esc(c.id)}" ${historyFilters.classId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.shift)}</option>`).join('')}</select></label><label>Student name or ID<input type="search" data-history-filter="q" value="${esc(historyFilters.q)}" placeholder="Search student"></label><label>Teacher<select data-history-filter="teacherId"><option value="all">All teachers</option>${teachers.map(t=>`<option value="${esc(t.id)}" ${historyFilters.teacherId===t.id?'selected':''}>${esc(t.fullName)}</option>`).join('')}<option value="admin" ${historyFilters.teacherId==='admin'?'selected':''}>Administrator</option></select></label><label>Status<select data-history-filter="status"><option value="all">All statuses</option>${['Present','Absent','Late','Excused'].map(s=>`<option ${historyFilters.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn btn-secondary history-apply" data-history-apply>Apply filters</button></div></article><article class="card history-table-card"><div class="table-responsive"><table class="attendance-history-table"><thead><tr><th>DATE</th><th>STUDENT</th><th>STUDENT ID</th><th>CLASS</th><th>TEACHER</th><th>STATUS</th><th>SAVED BY</th><th>SAVED TIME</th><th>CORRECT</th></tr></thead><tbody>${records.map(a=>`<tr><td>${pretty(a.date)}</td><td><button class="history-student-link" data-history-student="${esc(a.student.id)}">${esc(a.student.fullName)}</button></td><td>${esc(a.student.id)}</td><td>${esc(a.cls?.name||'—')}</td><td>${esc(a.teacher?.fullName||(a.recordedBy==='admin'?'Administrator':'—'))}</td><td><span class="badge ${statusBadge(a.status)}">${esc(a.status)}</span></td><td>${esc(a.recordedBy==='admin'?'Administrator':teachers.find(t=>t.id===a.recordedBy)?.fullName||a.recordedBy||'—')}</td><td>${a.updatedAt||a.createdAt?new Date(a.updatedAt||a.createdAt).toLocaleString():'Legacy record'}</td><td><select data-history-edit-status="${esc(a.studentId)}|${esc(a.classId||'')}|${esc(a.date)}">${['Present','Absent','Late','Excused'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="text-link" data-history-correct="${esc(a.studentId)}|${esc(a.classId||'')}|${esc(a.date)}">Save</button></td></tr>`).join('')||'<tr><td colspan="9"><div class="empty-state">No attendance records match these filters.</div></td></tr>'}</tbody></table></div><div class="table-footer">${records.length} matching attendance records. Student names open that student\'s history.</div></article></div>`;}
  function printAttendanceHistory(){const rows=filteredAttendanceHistory(),win=window.open('','_blank','width=1000,height=750');if(!win){toast('Allow pop-ups to print attendance history','alert-circle');return;}win.document.write(`<!doctype html><html><head><title>Attendance History</title><style>body{font:12px Arial;color:#0f172a;padding:24px}h1{color:#C2410C}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd}</style></head><body><h1>Al-Hikma Academy · Attendance History</h1><p>${rows.length} records</p><table><thead><tr><th>Date</th><th>Student</th><th>ID</th><th>Class</th><th>Teacher</th><th>Status</th><th>Saved by</th><th>Saved time</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.student.fullName)}</td><td>${esc(a.student.id)}</td><td>${esc(a.cls?.name||'—')}</td><td>${esc(a.teacher?.fullName||'—')}</td><td>${esc(a.status)}</td><td>${esc(a.recordedBy||'—')}</td><td>${a.updatedAt||a.createdAt?new Date(a.updatedAt||a.createdAt).toLocaleString():'Legacy record'}</td></tr>`).join('')}</tbody></table><script>window.print()<\/script></body></html>`);win.document.close();}
  function statusBadge(status){return status==='Present'?'badge-success':status==='Absent'?'badge-danger':status==='Late'?'badge-warning':'badge-neutral';}
  function studentsView(){const rows=filteredStudents();root().innerHTML=`<div class="page-enter">${head('Students','Manage enrollment, family information, class, and monthly fees.',`<button class="btn btn-secondary" data-adv-view="archived-students"><i data-feather="archive"></i> Archived students (${Store.getArchivedStudents().length})</button><button class="btn btn-primary" data-adv-action="open-student"><i data-feather="user-plus"></i> Register student</button>`)}<section class="card advanced-table-card"><div class="advanced-toolbar"><div class="search-box wide-search"><i data-feather="search"></i><input id="adv-student-search" value="${esc(feeFilters.q)}" placeholder="Search student, ID, parent, or phone…"></div><div class="advanced-filter-row"><select class="filter-select" data-filter="classId"><option value="all">All classes</option>${Store.getClasses().map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><select class="filter-select" data-filter="shift"><option value="all">All shifts</option>${['Morning','Afternoon','Evening'].map(s=>`<option>${s}</option>`).join('')}</select><select class="filter-select" data-filter="enrollment"><option value="all">All enrollment</option><option>Active</option><option>Inactive</option><option>Graduated</option></select></div></div><div class="table-responsive advanced-table-scroll"><table class="student-admin-table"><thead><tr><th>ID</th><th>STUDENT</th><th>CLASS & SHIFT</th><th>MONTHLY FEE</th><th>PARENT</th><th>PHONE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${studentRows(rows)}</tbody></table></div><div class="table-footer"><span>${rows.length} active-list students · ${Store.getStudents().length} total records</span><span>Enrollment status is separate from fee payment status.</span></div></section></div>`;$$('[data-filter]').forEach(el=>{el.value=feeFilters[el.dataset.filter]||'all';});}
  function filteredStudents(){return Store.searchStudents(feeFilters.q).filter(s=>(feeFilters.classId==='all'||!feeFilters.classId||s.classId===feeFilters.classId)&&(feeFilters.shift==='all'||s.shift===feeFilters.shift)&&(feeFilters.enrollment==='all'||s.enrollmentStatus===feeFilters.enrollment));}
