  function archivedStudentsView(){const rows=Store.getArchivedStudents();root().innerHTML=`<div class="page-enter">${head('Archived students','Archived profiles are excluded from active attendance and monthly billing, with all history retained.',`<button class="btn btn-secondary" data-adv-view="students"><i data-feather="arrow-left"></i> Back to students</button>`)}<section class="card advanced-table-card"><div class="table-responsive advanced-table-scroll"><table class="student-admin-table"><thead><tr><th>ID</th><th>STUDENT</th><th>CLASS & SHIFT</th><th>ARCHIVED</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(s=>{const c=Store.getClasses().find(x=>x.id===s.classId);return `<tr><td>${esc(s.id)}</td><td><strong>${esc(s.fullName)}</strong></td><td>${esc(c?.name||s.grade||'—')} · ${esc(s.shift||'—')}</td><td>${pretty(s.archivedAt)}</td><td><button class="btn btn-secondary btn-sm" data-student-restore="${esc(s.id)}"><i data-feather="rotate-ccw"></i> Restore</button></td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty-state"><i data-feather="archive"></i><strong>No archived students</strong><p>Students you remove from the directory will appear here.</p></div></td></tr>'}</tbody></table></div></section></div>`;}
  function studentDeleteModal(id){const s=Store.getStudents().find(x=>x.id===id);if(!s)return;const cls=Store.getClasses().find(c=>c.id===s.classId);modal().innerHTML=`<div class="modal-backdrop" data-adv-close><section class="modal student-delete-modal" role="dialog" aria-modal="true" aria-labelledby="student-delete-title"><div class="modal-header"><div><h2 id="student-delete-title">Student record actions</h2><p>Choose how to remove this student from the active directory.</p></div><button class="modal-close" data-adv-close aria-label="Close"><i data-feather="x"></i></button></div><div class="modal-body"><div class="student-delete-summary"><span><small>Student</small><strong>${esc(s.fullName)}</strong></span><span><small>Student ID</small><strong>${esc(s.id)}</strong></span><span><small>Class</small><strong>${esc(cls?.name||s.grade||'Unassigned')}</strong></span><span><small>Shift</small><strong>${esc(s.shift||cls?.shift||'—')}</strong></span></div><button type="button" class="student-delete-option student-archive-option" data-student-archive="${esc(id)}"><strong>Remove from Student List</strong><span>Archive the profile. Attendance, fees, receipts, and academic history stay available, and the student can be restored.</span></button><div class="student-delete-danger"><strong>Permanent deletion</strong><p>WARNING: This action will permanently delete this student's information, payment history, attendance records, and academic history. This action cannot be undone.</p><label for="student-delete-confirm">Type the student's full name to confirm</label><input id="student-delete-confirm" autocomplete="off" placeholder="${esc(s.fullName)}"><button type="button" class="btn btn-danger" data-student-permanent="${esc(id)}" disabled><i data-feather="trash-2"></i> Permanently Delete</button></div></div><div class="modal-footer"><button class="btn btn-secondary" data-adv-close>Cancel</button></div></section></div>`;feather.replace();}
  function downloadDeletionBackup(studentId){studentId=studentId||$('[data-student-permanent]')?.dataset.studentPermanent;const source=JSON.parse(localStorage.getItem('dugsiga-manager-data-v1')||'{}'),student=(source.students||[]).find(s=>s.id===studentId);if(!student)throw new Error('Could not create a backup: student record is missing');const matches=(rows=[])=>rows.filter(row=>row.studentId===studentId),fees=matches(source.fees);fees.forEach(f=>{f.payments=(f.payments||[]).map(p=>({...p}));});const backup={createdAt:new Date().toISOString(),purpose:'Pre-deletion student backup',student,attendance:matches(source.attendance),fees,payments:matches(source.payments),studentAcademicHistory:matches(source.studentAcademicHistory),promotions:matches(source.promotions),classes:(source.classes||[]).filter(c=>c.id===student.classId).map(c=>({...c,studentIds:(c.studentIds||[]).filter(id=>id===studentId)}))},payload=JSON.stringify(backup,null,2),url=URL.createObjectURL(new Blob([payload],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`dugsiga-student-${student.id}-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function feesView(){Store.generateMonthlyFees();const students=Store.getStudents(),fees=filteredFees(),totalDue=fees.reduce((s,f)=>s+f.amountDue,0),paid=fees.reduce((s,f)=>s+f.amountPaid,0),outstanding=fees.reduce((s,f)=>s+f.balance,0);root().innerHTML=`<div class="page-enter">${head('Maamulka Fiiga','Monthly billing, payment history, and outstanding balances.',`<button class="btn btn-secondary" data-adv-action="billing-settings"><i data-feather="settings"></i> Billing settings</button>`)}<div class="fee-summary"><article class="card"><small>Amount billed</small><strong>${cash(totalDue)}</strong></article><article class="card"><small>Collected</small><strong style="color:#0b9b6f">${cash(paid)}</strong></article><article class="card"><small>Outstanding</small><strong style="color:#C2410C">${cash(outstanding)}</strong></article></div><section class="card advanced-table-card"><div class="advanced-toolbar fee-toolbar"><div class="search-box wide-search"><i data-feather="search"></i><input id="fee-search-adv" value="${esc(feeFilters.q)}" placeholder="Search name, ID, parent, or phone…"></div><div class="advanced-filter-row"><select class="filter-select" data-fee-filter="classId"><option value="all">All classes</option>${Store.getClasses().map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><select class="filter-select" data-fee-filter="shift"><option value="all">All shifts</option>${['Morning','Afternoon','Evening'].map(s=>`<option>${s}</option>`).join('')}</select><select class="filter-select" data-fee-filter="enrollment"><option value="all">All enrollment</option><option>Active</option><option>Inactive</option></select><select class="filter-select" data-fee-filter="status"><option value="all">All payment status</option>${['Paid','Unpaid','Partial Payment','Overdue'].map(s=>`<option>${s}</option>`).join('')}</select><select class="filter-select" data-fee-filter="month"><option value="all">All months</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">${new Date(2026,i,1).toLocaleString('en-US',{month:'long'})}</option>`).join('')}</select><select class="filter-select" data-fee-filter="year"><option value="all">All years</option>${[...new Set(Store.getFees().map(f=>String(f.billingYear)))].sort().reverse().map(y=>`<option>${y}</option>`).join('')}</select></div></div><div class="table-responsive advanced-table-scroll"><table class="fee-admin-table"><thead><tr><th>STUDENT</th><th>ID</th><th>PARENT</th><th>PHONE</th><th>CLASS</th><th>MONTHLY FEE</th><th>LAST PAYMENT</th><th>PAYMENT STATUS</th><th>ACTION</th></tr></thead><tbody>${feeRows(fees)}</tbody></table></div><div class="table-footer"><span>${fees.length} monthly fee records · filters apply to the selected billing period</span><span>Payment entries preserve transaction history.</span></div></section></div>`;$$('[data-fee-filter]').forEach(el=>el.value=feeFilters[el.dataset.feeFilter]||'all');}
  function filteredFees(){const q=feeFilters.q.toLowerCase();return Store.getFees().filter(f=>{const s=Store.getStudents().find(x=>x.id===f.studentId),cls=Store.getClasses().find(c=>c.id===s?.classId);return(!q||[s?.fullName,s?.id,s?.parentName,s?.phone].some(v=>String(v||'').toLowerCase().includes(q)))&&(feeFilters.classId==='all'||s?.classId===feeFilters.classId)&&(feeFilters.shift==='all'||s?.shift===feeFilters.shift)&&(feeFilters.enrollment==='all'||s?.enrollmentStatus===feeFilters.enrollment)&&(feeFilters.status==='all'||f.status===feeFilters.status)&&(feeFilters.month==='all'||Number(f.billingMonth)===Number(feeFilters.month))&&(feeFilters.year==='all'||String(f.billingYear)===String(feeFilters.year));});}
  function feeRows(rows){if(!rows.length)return '<tr><td colspan="9"><div class="empty-state"><i data-feather="credit-card"></i><strong>No fee records match</strong><p>Try another month, year, or search.</p></div></td></tr>';return rows.map(f=>{const s=Store.getStudents().find(x=>x.id===f.studentId),cls=Store.getClasses().find(c=>c.id===s?.classId),last=(f.payments||[]).slice().sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate))[0],tone=f.status==='Paid'?'badge-success':f.status==='Overdue'?'badge-danger':f.status==='Partial Payment'?'badge-warning':'badge-neutral';return `<tr><td class="student-primary-cell"><div class="student-name"><span class="student-initials">${initals(s?.fullName||'?')}</span><span><strong>${esc(s?.fullName||'Student')}</strong><small>${esc(f.month)}</small></span></div></td><td>${esc(s?.id||'')}</td><td>${esc(s?.parentName||'—')}</td><td>${esc(s?.phone||'—')}</td><td>${esc(cls?.name||'Unassigned')}</td><td>${cash(f.amountDue)}<small class="table-subline">Balance ${cash(f.balance)}</small></td><td>${last?pretty(last.paymentDate):'—'}${last?`<small class="table-subline">${cash(last.amountPaid)} · ${esc(last.paymentMethod)}</small>`:''}</td><td><span class="badge ${tone}"><span class="badge-dot"></span>${esc(f.status)}</span></td><td><div class="table-actions"><button class="btn btn-primary btn-sm" data-record-payment="${esc(f.id)}" ${f.balance<=0?'disabled':''}>Record payment</button><button class="btn btn-secondary btn-sm" data-student-profile="${esc(s?.id)}">View profile</button></div></td></tr>`;}).join('');}
