  function openSubjectModal(subject=null,level='primary'){const edit=!!subject;modal().innerHTML=`<div class="modal-backdrop" data-adv-close><section class="modal"><div class="modal-header"><div><h2>${edit?'Edit subject':'Add a subject'}</h2><p>Subjects stay separated by education level.</p></div><button class="modal-close" data-adv-close><i data-feather="x"></i></button></div><form id="subject-form"><div class="modal-body"><div class="form-grid"><div class="form-field"><label>Subject name</label><input name="name" value="${esc(subject?.name||'')}" required></div><div class="form-field"><label>Somali name</label><input name="somali" value="${esc(subject?.somali||'')}"></div><div class="form-field full"><label>Education level</label><select name="educationLevel" ${edit?'disabled':''}><option value="primary" ${level==='primary'?'selected':''}>Primary School</option><option value="secondary" ${level==='secondary'?'selected':''}>Secondary School</option></select></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-adv-close>Cancel</button><button class="btn btn-primary">${edit?'Save changes':'Add subject'}</button></div></form></section></div>`;feather.replace();$('#subject-form').addEventListener('submit',e=>{e.preventDefault();const fields=Object.fromEntries(new FormData(e.currentTarget).entries());if(edit)Store.updateSubject(subject.id,fields);else Store.addSubject(fields);modal().innerHTML='';toast(edit?'Subject updated':'Subject added');render('subjects');});}
  function openYearModal(){modal().innerHTML=`<div class="modal-backdrop" data-adv-close><section class="modal"><div class="modal-header"><div><h2>Create academic year</h2><p>Set the official start and end dates.</p></div><button class="modal-close" data-adv-close><i data-feather="x"></i></button></div><form id="year-form"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>Academic year name</label><input name="name" required placeholder="2027/2028"></div><div class="form-field"><label>Start date</label><input name="startDate" type="date" required></div><div class="form-field"><label>End date</label><input name="endDate" type="date" required></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-adv-close>Cancel</button><button class="btn btn-primary">Create year</button></div></form></section></div>`;feather.replace();$('#year-form').addEventListener('submit',e=>{e.preventDefault();try{Store.addAcademicYear(Object.fromEntries(new FormData(e.currentTarget).entries()));modal().innerHTML='';toast('Academic year created');render('academic-years');}catch(err){toast(err.message,'alert-circle');}});}
  function assignmentSubjectOptions(classId,teacherId){const cls=Store.getClasses().find(c=>c.id===classId),assignment=Store.getTeacherAssignments().find(a=>a.classId===classId&&a.teacherId===teacherId),selected=new Set(assignment?.subjectIds||[]);return Store.getSubjects(cls?.educationLevel||'primary').map(s=>`<label><input type="checkbox" name="subjectIds" value="${esc(s.id)}" ${selected.has(s.id)?'checked':''}><span>${esc(s.name)}</span></label>`).join('')||'<small>No subjects are available for this class level.</small>';}
